import '../core/network/api_client.dart'; import '../core/network/api_exception.dart'; import '../models/shipping.dart'; class ShippingRepository { ShippingRepository(this._api); final ApiClient _api; Future<ShippingModel?> byOrder(String orderId) async { try{return ShippingModel.fromJson(Map<String,dynamic>.from(await _api.get('/api/shipping/orders/$orderId')));}on ApiException catch(e){if(e.statusCode==404)return null;rethrow;} } }
